package com.tarapickle.identity.domain.model; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*;
@Entity @Table(name="consent_records") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class ConsentRecord { @Id private UUID id; @Column(name="user_id") private UUID userId; @Column(name="consent_type") private String type; @Column(name="document_version") private String documentVersion; @Column(name="accepted_at") private Instant acceptedAt; public ConsentRecord(UUID uid,String type,String version,Instant at){id=UUID.randomUUID();userId=uid;this.type=type;documentVersion=version;acceptedAt=at;} }
